out = []


def _x(i):
    return round((i - OX) * S + PAD, 1)


def _y(i):
    return round((i - OY) * S + PAD, 1)


def _px(i):
    return round(i * S, 1)


def _pt(size):
    return round(size * S / 72, 1)


def e(s):
    return html.escape(str(s), quote=True)


def rbox(x, y, w, h, fill='#FFFFFF', stroke=LINE, adj=0.05, width=1.2):
    r = round(adj * min(_px(w), _px(h)), 1)
    stroke_attr = f' stroke="{stroke}" stroke-width="{width}"' if stroke else ''
    out.append(f'<rect x="{_x(x)}" y="{_y(y)}" width="{_px(w)}" height="{_px(h)}" rx="{r}" fill="{fill}"{stroke_attr}/>')


def circle(cx, cy, d, fill, stroke=None):
    st = f' stroke="{stroke}" stroke-width="1.2"' if stroke else ''
    out.append(f'<circle cx="{_x(cx)}" cy="{_y(cy)}" r="{_px(d) / 2}" fill="{fill}"{st}/>')


def icon(name, x, y, s=0.26, color=BLUE):
    vb, inner = ICONS[name]
    _a, _b, vw, vh = (float(v) for v in vb.split())
    k = _px(s) / max(vw, vh)                      # fit the icon's box, centred, aspect kept
    tx = _x(x) + (_px(s) - vw * k) / 2
    ty = _y(y) + (_px(s) - vh * k) / 2
    out.append(f'<g transform="translate({tx:.1f},{ty:.1f}) scale({k:.5f})" fill="{color}" '
               f'aria-hidden="true">{inner}</g>')


def arrow(x, y, w, h, color=BLUE, down=False):
    X, Y, W_, H_ = _x(x), _y(y), _px(w), _px(h)
    if down:
        pts = [(X + W_ * .25, Y), (X + W_ * .75, Y), (X + W_ * .75, Y + H_ * .5), (X + W_, Y + H_ * .5),
               (X + W_ / 2, Y + H_), (X, Y + H_ * .5), (X + W_ * .25, Y + H_ * .5)]
    else:
        pts = [(X, Y + H_ * .25), (X + W_ * .5, Y + H_ * .25), (X + W_ * .5, Y), (X + W_, Y + H_ / 2),
               (X + W_ * .5, Y + H_), (X + W_ * .5, Y + H_ * .75), (X, Y + H_ * .75)]
    out.append(f'<polygon points="{" ".join(f"{a:.1f},{b:.1f}" for a, b in pts)}" fill="{color}"/>')


def _wrap(text, max_px, size_px, bold):
    """Greedy word wrap with a conservative average glyph width (no font metrics in SiS)."""
    per = size_px * (0.53 if bold else 0.5)
    words, lines, cur = str(text).split(), [], ''
    for word in words:
        trial = (cur + ' ' + word).strip()
        if cur and len(trial) * per > max_px:
            lines.append(cur)
            cur = word
        else:
            cur = trial
    if cur:
        lines.append(cur)
    return lines or ['']


def text(x, y, w, h, paras, anchor='top', align='left', gap=0.0):
    """paras: list of paragraphs, each a list of runs (text, pt, bold, color).
    A one-run paragraph wraps to the box width; a multi-run paragraph stays on one line."""
    lines = []                                    # (runs, line height px)
    for runs in paras:
        size = max(_pt(r[1]) for r in runs)
        if len(runs) == 1:
            t, pt, b, c = runs[0]
            for part in _wrap(t, _px(w), _pt(pt), b):
                lines.append(([(part, pt, b, c)], size * 1.22))
        else:
            lines.append((runs, size * 1.22))
        if gap:
            lines[-1] = (lines[-1][0], lines[-1][1] + _pt(gap))
    total = sum(lh for _r, lh in lines)
    top = _y(y) + (_px(h) - total) / 2 if anchor == 'middle' else _y(y)
    if align == 'center':
        xpos, ta = _x(x) + _px(w) / 2, 'middle'
    else:
        xpos, ta = _x(x), 'start'
    cy = top
    for runs, lh in lines:
        size = max(_pt(r[1]) for r in runs)
        base = cy + size * 0.95
        spans = ''.join(f'<tspan font-size="{_pt(pt)}" font-weight="{700 if b else 400}" fill="{c}">{e(t)}</tspan>'
                        for t, pt, b, c in runs)
        out.append(f'<text x="{xpos}" y="{base:.1f}" text-anchor="{ta}" xml:space="preserve">{spans}</text>')
        cy += lh


def section_label(x, y, w, h, title, sub=None, color=NAVY, size=9.5):
    paras = [[(title, size, True, color)]]
    if sub:
        paras.append([(sub, 7.5, False, INK)])
    text(x, y, w, h, paras, gap=2)


def card(x, y, w, h, name, head, sub=None, head_size=8.5, sub_size=7, iy=None):
    rbox(x, y, w, h, adj=0.15)
    icon(name, x + 0.1, y + (h - 0.26) / 2 if iy is None else iy)
    paras = [[(head, head_size, True, INK)]] + ([[(sub, sub_size, False, MUTED)]] if sub else [])
    text(x + 0.46, y + 0.02, w - 0.52, h - 0.04, paras, anchor='middle')


def _draw():
    TOP, BOT = 1.12, 5.02
    IN_TOP, IN_BOT = 1.56, 4.94
    MID = 3.0

    # 1. Tableau sources
    rbox(0.3, TOP, 1.75, BOT - TOP)
    section_label(0.42, TOP + 0.07, 1.6, 0.4, 'TABLEAU SOURCES', 'workbooks and their data')
    for i, (n, h, s) in enumerate([('Cloud', 'Tableau Cloud', 'or Server (REST API)'),
                                   ('FileUpload', 'File upload', '.twb / .twbx'),
                                   ('FileExcel', 'Bundled data', 'Excel, CSV, Hyper'),
                                   ('Plug', 'Live connections', 'joins, custom SQL'),
                                   ('Table', 'Tableau values', 'view data, captures'),
                                   ('Snowflake', 'Snowflake data', 'used in place')]):
        card(0.4, 1.6 + i * 0.555, 1.55, 0.49, n, h, s)
    arrow(2.08, MID, 0.22, 0.18)

    # 2. Snowflake account
    rbox(2.34, TOP, 8.0, BOT - TOP, stroke=BLUE, adj=0.03)
    icon('Snowflake', 4.6, TOP + 0.08, 0.28)
    text(4.95, TOP + 0.1, 5.2, 0.3, [[('SNOWFLAKE AI DATA CLOUD', 12, True, BLUE),
                                      ('   one account, nothing leaves it', 8.5, False, INK)]])

    rbox(2.46, IN_TOP, 1.82, IN_BOT - IN_TOP, fill=PANEL)
    section_label(2.58, IN_TOP + 0.07, 1.62, 0.3, 'INGEST & CONVERT')
