ARIA_LABEL = (
    'Tableau to Streamlit accelerator architecture. Left: Tableau sources: Tableau Cloud or Server, file upload, '
    'bundled Excel, CSV and Hyper data, live connections, Tableau values and existing Snowflake data. Middle, '
    'inside one Snowflake account: ingest and convert (workbook parser, workbook model, source resolver, model '
    'planner, app generator); governed data foundation (tables and views, semantic views proven equal to the '
    'source, verified sheets); Cortex AI and migration intelligence (AI_COMPLETE, Cortex Analyst, model design, '
    'Cortex Agents, vision compare, chart plans, and accelerator engines for calc check, cause proof, diff '
    'diagnosis, fix approval and report writing). Right: applications and outputs (Migration Portal, migrated '
    'apps, Ask the data, Tableau comparison, migration report, approved deploy) for the migration team, reviewers, '
    'business users and leaders. Below: three-step validation of every sheet before deploy (data, calculation, '
    'visual), then governance (roles, secrets, human approval, evidence store, AI ledger, release gate).'
)


def build_svg_fragment():
    """Returns (svg_markup, W, H): the board only, ready to inline into the console."""
    out.clear()
    h = _draw()
    w = round(12.74 * S + 2 * PAD)
    body = ''.join(out)
    svg = (f'<svg viewBox="0 0 {w} {h}" xmlns="http://www.w3.org/2000/svg" role="img" '
           f'aria-label="{e(ARIA_LABEL)}" style="display:block;width:100%;height:auto">'
           f'<g font-family="{e(FONT)}">{body}</g></svg>')
    return svg, w, h


def build_standalone_page():
    """Self-contained HTML page with the board, for sharing outside the app."""
    svg, w, _h = build_svg_fragment()
    return (f'<title>Tableau to Streamlit Accelerator — Architecture</title>'
            f'<style>body{{margin:0;background:{BACKGROUND};font-family:{FONT}}}'
            f'.wrap{{max-width:{w + 40}px;margin:0 auto;padding:20px}}h1{{color:{NAVY};font-size:26px;margin:0 0 12px}}'
            f'.wrap svg{{min-width:1100px}}</style>'
            f'<div class="wrap"><h1>Tableau to Streamlit Accelerator on the Snowflake AI Data Cloud</h1>{svg}</div>')


if __name__ == '__main__':
    with open('Platform-Architecture-V3.html', 'w', encoding='utf-8') as f:
        f.write(build_standalone_page())
    print('wrote Platform-Architecture-V3.html')
